def backfill_discount_applied(apps, schema_editor):
    """Fix each existing allocation's discount slice at what the GL already posted.

    The ledger journal credited AR with ``round(allocation / receipt.amount * discount)``; the
    sub-ledger used a different denominator, so the two disagreed on partial allocations. The
    posted journal is the record, so the stored column takes its value and the invoice balance
    now follows the books. Reversed rows are filled too, so a re-run changes nothing.
    """
    from decimal import ROUND_HALF_UP, Decimal

    PaymentAllocation = apps.get_model("payments", "PaymentAllocation")
    qs = PaymentAllocation.objects.filter(
        receipt__isnull=False, receipt__settlement_discount__gt=0, discount_applied=0
    ).select_related("receipt")
    for alloc in qs.iterator(chunk_size=500):
        base = Decimal(alloc.receipt.amount or 0)
        discount = Decimal(alloc.receipt.settlement_discount or 0)
        if base <= 0:
            continue
        share = (Decimal(alloc.amount) / base * discount).quantize(
            Decimal("0.01"), rounding=ROUND_HALF_UP
        )
        share = min(share, discount)
        if share > 0:
            PaymentAllocation.objects.filter(pk=alloc.pk).update(discount_applied=share)


